package android.graphics;
import java.awt.image.BufferedImage;
public class Bitmap {public final BufferedImage image;public Bitmap(BufferedImage image){this.image=image;}public int getWidth(){return image.getWidth();}public int getHeight(){return image.getHeight();}public boolean isRecycled(){return false;}public enum Config{ARGB_8888}public static Bitmap createBitmap(int w,int h,Config c){return new Bitmap(new BufferedImage(w,h,BufferedImage.TYPE_INT_ARGB));}public static Bitmap createBitmap(Bitmap source,int x,int y,int w,int h){return new Bitmap(source.image.getSubimage(x,y,w,h));}public void getPixels(int[] p,int offset,int stride,int x,int y,int w,int h){image.getRGB(x,y,w,h,p,offset,stride);}public void setPixels(int[] p,int offset,int stride,int x,int y,int w,int h){image.setRGB(x,y,w,h,p,offset,stride);}}

